import {PART_SPECS} from './part-specs.js';
import * as T from './vendor/three.module.js';
import {stabilityReport,createTopple,stepTopple,pushTopple,placeOnFloor} from './stability.js';
import {component,exportModel,parseModel,V} from './engine.js';
import {setGrounded} from './grounding.js';
export function createStabilityUI({scene,getModel,getSelected,stopOthers,changed,sync,record,restore,redraw,toast,onRunning,loadExample}){
 const $=s=>document.querySelector(s),panel=$('#stability-panel'),overlay=new T.Group();scene.add(overlay);let open=false,body=null,baseline=null,dirty=true,last=0,report=null,modelRef=getModel();
 function clear(){for(const o of [...overlay.children]){o.geometry?.dispose();o.material?.dispose();overlay.remove(o);}}
 function draw(r){clear();const color=r.anchors.length?'#e4b56b':r.stable?'#65dcc1':'#ff806e',points=r.hull.map(p=>V([p.x,.8,p.z]));if(points.length){points.push(points[0].clone());overlay.add(new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color,depthTest:false})));}const center=r.center.clone(),down=V([center.x,.8,center.z]);overlay.add(new T.Line(new T.BufferGeometry().setFromPoints([center,down]),new T.LineDashedMaterial({color,dashSize:4,gapSize:3,depthTest:false})));overlay.children.at(-1).computeLineDistances();for(const[pos,size]of[[center,4],[down,2.5]]){const m=new T.Mesh(new T.SphereGeometry(size,12,8),new T.MeshBasicMaterial({color,depthTest:false}));m.position.copy(pos);m.renderOrder=200;overlay.add(m);}for(const o of overlay.children)o.renderOrder=200;}
 function activeId(){const m=getModel(),id=getSelected();return m.parts.some(p=>p.id===id)?id:m.parts[0]?.id;}
 function refresh(){if(!open)return;dirty=false;try{const m=getModel(),id=activeId();if(!id)throw Error('Add parts or load the balance example.');report=stabilityReport(m,id);const r=report;$('#stability-state').textContent=body?`Testing · ${body.phase}`:r.anchors.length?'Anchored to the world':r.stable?'Stable on a level floor':r.status==='unstable'?'Outside the support footprint':'Balanced on an edge';$('#stability-state').dataset.state=r.anchors.length?'anchored':r.stable?'stable':'unstable';$('#stability-details').textContent=`${r.ids.size} connected parts · ${r.mass.toFixed(1)} g\n${Math.abs(r.margin).toFixed(1)} mm ${r.margin>=0?'inside':'outside'} the nearest support edge\nCenter of mass: ${(r.center.y-r.bottom).toFixed(1)} mm above its lowest support`;
 $('#stability-source').textContent=`${r.overrides} assigned masses; ${[...r.ids].filter(id=>{const p=m.parts.find(p=>p.id===id);return p.massG===undefined&&PART_SPECS[p.type];}).length} supplier weights; ${[...r.ids].filter(id=>{const p=m.parts.find(p=>p.id===id);return p.massG===undefined&&!PART_SPECS[p.type];}).length} estimates. Rigid build test: joints are held at their current pose. Starts seated on a flat floor. Ground impacts stop motion; no bounce.`;$('#stability-run').disabled=!!r.anchors.length&&!body;$('#stability-run').textContent=body?'Pause test':'Run gravity';$('#stability-floor').disabled=!!body||!!r.anchors.length;$('#stability-release').hidden=!r.anchors.length;$('#stability-reset').disabled=!baseline;$('#stability-push').disabled=!!r.anchors.length;draw(r);redraw();
 }catch(e){report=null;clear();$('#stability-state').textContent=e.message;$('#stability-details').textContent='';$('#stability-run').disabled=true;$('#stability-push').disabled=true;$('#stability-floor').disabled=true;}}
 function stop(){if(!body)return;body=null;onRunning(false);if(baseline&&exportModel(getModel())!==baseline)record(baseline);dirty=true;changed();}
 function start(){stopOthers();const m=getModel();baseline=exportModel(m);try{body=createTopple(m,activeId());onRunning(true);sync();dirty=true;refresh();}catch(e){body=null;baseline=null;toast(e.message);refresh();}}
 function toggle(force){open=force??!open;if(!open)stop();panel.hidden=!open;overlay.visible=open;document.body.classList.toggle('stability-open',open);if(open){stopOthers();refresh();}redraw();}
 $('#stability-run').onclick=()=>body?stop():start();
 $('#stability-floor').onclick=()=>{stopOthers();try{const before=exportModel(getModel());placeOnFloor(getModel(),report.ids);record(before);baseline=null;changed();refresh();}catch(e){toast(e.message);}};
 $('#stability-release').onclick=()=>{stopOthers();const before=exportModel(getModel());setGrounded(getModel(),report.ids,false);record(before);baseline=null;changed();refresh();};
 $('#stability-reset').onclick=()=>{if(!baseline)return;const original=baseline;stop();record(exportModel(getModel()));restore(parseModel(original));baseline=null;changed();refresh();};
 $('#stability-push').onclick=()=>{if(!body)start();if(!body)return;try{pushTopple(body,JSON.parse($('#stability-direction').value),Number($('#stability-impulse').value));refresh();}catch(e){toast(e.message);}};
 $('#stability-example').onclick=()=>{stop();loadExample('balance');toggle(true);toast('Select Payload in Scene. Change its assigned mass from its default to 250 g to compare stability.');};
 return{stop,toggle,invalidate(){if(modelRef!==getModel()){modelRef=getModel();baseline=null;}dirty=true;},get running(){return !!body;},tick(time,dt){if(body){try{if(stepTopple(getModel(),body,dt)){sync();dirty=true;}}catch(e){stop();toast(e.message);}}if(open&&dirty&&time-last>120){last=time;refresh();}},dispose(){stop();clear();scene.remove(overlay);}};
}
